]);

/*
  ParallelListeners prevents entire app from rerendering on any change in the listeners,
  most of which interact with redux etc.
*/
function App() {
  return (
    <VscThemeProvider>
      <MainEditorProvider>
          <RouterProvider router={router} />
      </MainEditorProvider>
      <ParallelListeners />
    </VscThemeProvider>
  );
}

