    hasDoneInitialConfigLoad.current = true;
    dispatch(setConfigLoading(false));
  }, []);

  useWebviewListener(
    "configUpdate",
    async (update: any) => {
      if (!update) {
        return;
      }
      await handleConfigUpdate(false, update);
    },
    [handleConfigUpdate],
