import { useEffect, useRef, useState } from "react";

export function useAppendedString(
  fullString: string,
  append: (chunk: string, lineCount: number) => void,
) {
  // Queue of fullString updated versions to be processed atomically
  const [updateQueue, setUpdateQueue] = useState<string[]>([]);
  const lastString = useRef("");
  const processing = useRef(false);

  useEffect(() => {
    setUpdateQueue((prev) => [...prev, fullString]);
  }, [fullString]);

  useEffect(() => {
    if (updateQueue.length === 0 || processing.current) return;

    processing.current = true;
    setUpdateQueue((currentQueue) => {
      while (currentQueue.length > 0) {
        const nextString = currentQueue.shift()!;
        if (!nextString.startsWith(lastString.current)) {
          // Invalid
          continue;
        }
        const appendedPart = nextString.slice(lastString.current.length);
        lastString.current = nextString;
        append(appendedPart, lastString.current.split("\n").length);
      }
      return currentQueue;
    });
    processing.current = false;
  }, [updateQueue]);
}

import { useState } from "react";

function useArrayState<T>(initialValue: T[]) {
  const [value, setValue] = useState(initialValue);

  function add(item: any) {
    setValue((prev) => [...prev, item]);
  }

  function remove(index: number) {
    setValue((prev) => prev.filter((_, i) => i !== index));
  }

  function edit(editFn: (prev: T[]) => T[]) {
    setValue((prev) => editFn(prev));
  }

  function replace(atIndex: number, withItem: T) {
    setValue((prev) => {
      let updated = [...prev];
      updated[atIndex] = withItem;
      return updated;
    });
  }

  return { value, add, remove, edit, replace };
}

export default useArrayState;

import { SlashCommandDescWithSource } from "core";

import { useAppDispatch, useAppSelector } from "../redux/hooks";
import {
  bookmarkSlashCommand,
  selectBookmarkedSlashCommands,
  unbookmarkSlashCommand,
} from "../redux/slices/profilesSlice";

export function useBookmarkedSlashCommands() {
  const dispatch = useAppDispatch();
  const bookmarkedCommands = useAppSelector(selectBookmarkedSlashCommands);

  const isCommandBookmarked = (commandName: string): boolean => {
    return bookmarkedCommands.includes(commandName);
  };

  const toggleBookmark = (command: SlashCommandDescWithSource) => {
    const isBookmarked = isCommandBookmarked(command.name);

    if (isBookmarked) {
      dispatch(
        unbookmarkSlashCommand({
          commandName: command.name,
        }),
      );
    } else {
      dispatch(
        bookmarkSlashCommand({
          commandName: command.name,
        }),
      );
    }
  };

  return {
    isCommandBookmarked,
    toggleBookmark,
  };
}

import { useState, useContext, useCallback } from "react";
