}

function removeInteractionFromLLMLog(
  llmLog: LLMLog,
  interactionId: string,
): LLMLog {
  const newInteractions = new Map(llmLog.interactions);
  newInteractions.delete(interactionId);
  const newOrder = llmLog.order.filter((id) => id !== interactionId);

  return {
    loading: false,
    interactions: newInteractions,
    order: newOrder,
  };
}

/**
 * Hook to accumulate log data structures based on messages passed
 * from the core. Note that each call site will create an independent
 * data structure, so this should be only used once at a toplevel
 * component.
 * @returns currently log datastructure.
 */
export default function useLLMLog() {
  const [llmLog, dispatchLlmLog] = useReducer(
    (llmLog: LLMLog, message: ToConsoleView) => {
      switch (message.type) {
        case "init":
          return appendItemsToLLMLog(llmLog, message.items);
        case "item":
          return appendItemsToLLMLog(llmLog, [message.item]);
        case "remove":
          return removeInteractionFromLLMLog(llmLog, message.interactionId);
        case "clear":
          return {
            loading: false,
            interactions: new Map(),
            order: [],
          };
      }
    },
    {
      loading: true,
      interactions: new Map(),
      order: [],
    },
  );

  useEffect(function () {
    // The uuid here marks the "generation" when the webview is
    // reloaded, so we don't get confused if there are inflight
    // messages from the previous generation. In particular, this
    // avoids problems when React.StrictMode runs this effect
    // twice - we don't want to process two "init" messages.
    const uuid = uuidv4();
    const onMessage = (event: MessageEvent<ToConsoleView>) => {

    // twice - we don't want to process two "init" messages.
    const uuid = uuidv4();
    const onMessage = (event: MessageEvent<ToConsoleView>) => {
      if (event.data.uuid !== uuid) {
        return;
      }

      dispatchLlmLog(event.data);
    };
    window.addEventListener("message", onMessage);
    vscode.postMessage({ type: "start", uuid });

    return () => {
      vscode.postMessage({ type: "stop", uuid });
      window.removeEventListener("message", onMessage);
    };
  }, []);

  return llmLog;
}

import { CSSProperties, useEffect, useRef } from "react";

/**
 * useRenderDebug
 *
 * Developer utility to visualize component re-renders.
 *
 * - Returns a `ref` to attach to a container element and a `count` that
 *   increments on every render of the component using this hook.
 * - On each render, it briefly adds a CSS class (default: `rerender-flash`)
 *   to the element for a quick visual flash.
 * - Use together with <RenderCountBadge /> to show the render count inline.
 *
 * Options:
 * - enabled: boolean to toggle the effect (default true)
 * - flashClassName: class added on each render (default `rerender-flash`)
 * - flashDurationMs: duration of the flash animation in ms (default 180)
 */

export function useRenderDebug(options?: {
  enabled?: boolean;
  flashClassName?: string;
  flashDurationMs?: number;
}) {
  const {
    enabled = true,
    flashClassName = "rerender-flash",
    flashDurationMs = 180,
  } = options || {};

  const ref = useRef<HTMLElement | null>(null);
  const countRef = useRef(0);
  countRef.current += 1;

  useEffect(() => {
    if (!enabled || !ref.current) return;
    const el = ref.current;
    el.classList.add(flashClassName);
    const t = setTimeout(
      () => el.classList.remove(flashClassName),
      flashDurationMs,
    );
    return () => {
      clearTimeout(t);
      // Ensure we don't leave the flash class applied on cleanup
      el.classList.remove(flashClassName);
    };
  });

  return { ref, count: countRef.current, countRef } as const;
}

export function RenderCountBadge(props: {
  count: number;
  title?: string;
  style?: CSSProperties;
  className?: string;
}) {

  style?: CSSProperties;
  className?: string;
}) {
  // Simple badge for use with useRenderDebug; keep lightweight.
  const { count, title = `Renders: ${count}`, style, className } = props;
  return (
    <span
      className={`render-count ${className || ""}`}
      title={title}
      style={style}
    >
      R{count}
    </span>
  );
}

import { useEffect, useRef } from "react";

function useUpdatingRef<T>(value: T, deps: any[] = []) {
  const ref = useRef(value);

  useEffect(() => {
    ref.current = value;
  }, [value, ...deps]);

  return ref;
}

export default useUpdatingRef;

