  "ruby",
  "bundle",
];

export function isTerminalCodeBlock(
  language: string | undefined | null,
  text: string,
) {
  return (
    (language && terminalLanguages.includes(language)) ||
    ((!language || language?.length === 0) &&
      (text.trim().split("\n").length === 1 ||
        commonTerminalCommands.some((c) => text.trim().startsWith(c))))
  );
}

function childToText(child: any): string {
  if (typeof child === "string") {
    return child;
  } else if (child?.props) {
    return childToText(child.props?.children);
  } else if (Array.isArray(child)) {
    return childrenToText(child);
  } else {
    return "";
  }
}

export function childrenToText(children: any) {
  return children.map((child: any) => childToText(child)).join("");
}

export function matchCodeToSymbolOrFile(
  content: string,
  symbols: SymbolWithRange[],
  rifs: RangeInFileWithContents[],
): SymbolWithRange | RangeInFileWithContents | undefined {
  // Insert file links for matching previous context items
  // With some reasonable limitations on what might be a filename
  if (rifs.length && content.includes(".") && content.length > 2) {
    const match = rifs.find(
      (rif) => rif.filepath.split("/").pop() === content, // Exact match for last segment of URI
    );

    if (match) {
      return match;
    }
  }

    }
  }

  // Insert symbols for exact matches
  const exactSymbol = symbols.find((s) => s.name === content);
  if (exactSymbol) {
    return exactSymbol;
  }

  // Partial matches - this is the case where the llm returns e.g. `subtract(number)` instead of `subtract`
  const partialSymbol = symbols.find((s) => content.startsWith(s.name));
  if (partialSymbol) {
    return partialSymbol;
  }
}

export function isSymbolNotRif(
  item: SymbolWithRange | RangeInFileWithContents,
): item is SymbolWithRange {
  return (item as SymbolWithRange).type !== undefined;
}

/**
 * Extracts and processes command strings, handling comments and line continuations.
 * @param cmd The command string to process
 * @returns The processed command string
 */
export function extractCommand(cmd: string): string {
  if (!cmd || cmd.trim() === "") {
    return "";
  }

  // Remove multi-line comments (/* ... */) and replace with a single space
  cmd = cmd.replace(/\/\*[\s\S]*?\*\//g, " ");

  // Handle the $ prompt case first
  if (cmd.includes("$")) {
    const match = cmd.match(/\$\s*([^\n]+)/);
    if (match) {
      // Return just the command after $ without further processing
      return match[1].trim();
    }
  }

  // Process lines - remove single-line comments only at beginning of lines
  const lines = cmd
    .split("\n")
    .map((line) => line.replace(/^\s*#.*$/, "").replace(/^\s*\/\/.*$/, ""))
    .map((line) => line.trim())
    .filter((line) => line);

  // Join lines with proper handling of continuations
  let result = "";
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i];

    // Remove trailing continuation characters and join with next line
    while (
      (line.endsWith("&&") || line.endsWith("|") || line.endsWith("\\")) &&
      i < lines.length - 1
    ) {
      // Remove the continuation character(s) and any trailing spaces
      line = line.replace(/(&&|\||\\)\s*$/, "").trim();
      // Join with the next line
      i++;
      line += " " + lines[i];
    }

    result += line + " ";
  }

  return result.trim().replace(/\s+/g, " ");
}

/*
Currently double dollar latext with new lines causes truncation error
So this pseudo-remark plugin removes internal newlines with double dollar signs
*/
export function fixDoubleDollarNewLineLatex(text: string): string {
  // Match LaTeX blocks delimited by $$ with newlines
  const pattern = /\$\$(?:\r?\n)(.*?)(?:\r?\n)\$\$/gms;

  // Replace each matched block with $$ without newline
  const replacedText = text.replace(pattern, "$$$$$1$$$$");

  return replacedText;
}

