                )
              )}
              <span className="text-xs">{option.title}</span>
            </div>
            {selected && (
              <CheckIcon
                className="h-3 w-3"
                aria-hidden="true"
              />
            )}
          </>
        )}
      </ListboxOption>
    ))}
  </div>
)}
{filteredTopOptions.length > 0 &&
  filteredOtherOptions.length > 0 && (
