  } else if (fileSize > MB) {
    return `${(fileSize / MB).toFixed(1)} MB`;
  } else if (fileSize > KB) {
    return `${(fileSize / KB).toFixed(1)} KB`;
  }

  return `${fileSize} byte${fileSize > 1 ? "s" : ""}`;
};

