/**
 * Typed message protocol between webview and extension host.
 * 
 * All communication goes through VS Code's postMessage mechanism.
 * Messages are validated on receipt — the webview never has direct filesystem
 * or network access.
 */

import { IndexingProgress } from '../indexing/types';

// ─── Messages from Webview to Extension ────────────────────────────────────

export type WebviewToExtensionMessage =
  | { type: 'sendMessage'; text: string; contextFiles?: string[] }
  | { type: 'cancelGeneration' }
  | { type: 'newChat' }
  | { type: 'approveAction'; approved: boolean }
  | { type: 'getConfig' }
  | { type: 'setProvider'; provider: string }
  | { type: 'setModel'; model: string }
  | { type: 'setApiKey'; provider: string; key: string }
  | { type: 'testConnection' }
  | { type: 'startIndexing'; fullReindex?: boolean }
  | { type: 'cancelIndexing' }
  | { type: 'getIndexStatus' }
  | { type: 'executeCommand'; command: string; args?: unknown[] }
  | { type: 'webviewReady' };

// ─── Messages from Extension to Webview ────────────────────────────────────

export type ExtensionToWebviewMessage =
  | { type: 'streamContent'; content: string }
  | { type: 'streamDone' }
  | { type: 'streamError'; error: string }
  | { type: 'streamCancelled' }
  | { type: 'toolCall'; toolName: string; args: Record<string, unknown> }
  | { type: 'toolResult'; toolName: string; content: string; success: boolean }
  | { type: 'approvalRequest'; toolName: string; description: string; diff?: string; filepath?: string }
  | { type: 'config'; provider: string; model: string; hasApiKey: boolean; availableProviders: string[] }
  | { type: 'connectionResult'; success: boolean; models?: string[]; error?: string }
  | { type: 'indexingProgress'; progress: IndexingProgress }

  | { type: 'config'; provider: string; model: string; hasApiKey: boolean; availableProviders: string[] }
  | { type: 'connectionResult'; success: boolean; models?: string[]; error?: string }
  | { type: 'indexingProgress'; progress: IndexingProgress }
  | { type: 'indexStatus'; indexed: boolean; entryCount: number; fileCount: number; inProgress: boolean }
  | { type: 'addContext'; filepath: string; content?: string; selection?: string };

/**
 * Validate that a message from the webview is well-formed.
 * Returns the validated message or null if invalid.
 */
export function validateWebviewMessage(data: unknown): WebviewToExtensionMessage | null {
  if (typeof data !== 'object' || data === null) {
    return null;
  }

  const msg = data as Record<string, unknown>;
  if (typeof msg.type !== 'string') {
    return null;
  }

  const validTypes: Set<string> = new Set([
    'sendMessage', 'cancelGeneration', 'newChat', 'approveAction',
    'getConfig', 'setProvider', 'setModel', 'setApiKey',
    'testConnection', 'startIndexing', 'cancelIndexing',
    'getIndexStatus', 'executeCommand', 'webviewReady',
  ]);

  if (!validTypes.has(msg.type)) {
    return null;
  }

  // Type-specific validation
  switch (msg.type) {
    case 'sendMessage':
      if (typeof msg.text !== 'string' || msg.text.trim().length === 0) {
        return null;
      }
      break;
    case 'approveAction':
      if (typeof msg.approved !== 'boolean') {
        return null;
      }
      break;
    case 'setProvider':
      if (typeof msg.provider !== 'string') {
        return null;
      }
      break;
    case 'setModel':
      if (typeof msg.model !== 'string') {
        return null;
      }
      break;
    case 'setApiKey':
      if (typeof msg.provider !== 'string' || typeof msg.key !== 'string') {
        return null;

    case 'setApiKey':
      if (typeof msg.provider !== 'string' || typeof msg.key !== 'string') {
        return null;
      }
      break;
    case 'executeCommand':
      if (typeof msg.command !== 'string') {
        return null;
      }
      break;
  }

  return msg as WebviewToExtensionMessage;
}

import * as vscode from 'vscode';

/**
 * Generate a strict Content Security Policy for the webview.
 * 
 * Prevents execution of inline scripts (except our specific nonce),
 * restricts connect-src (since API calls happen in the extension host, not webview),
 * and prevents framing.
 */
export function getCsp(webview: vscode.Webview, nonce: string): string {
  return [
    `default-src 'none'`,
    // Allow styles from the extension uri and inline styles (needed by React sometimes)
    `style-src ${webview.cspSource} 'unsafe-inline'`,
    // Allow scripts with the generated nonce, plus standard webview sources
    `script-src ${webview.cspSource} 'unsafe-inline' 'unsafe-eval' 'nonce-${nonce}'`,
    // Allow fonts if needed
    `font-src ${webview.cspSource}`,
    // The webview doesn't make direct API calls — all network happens in the extension host
    `connect-src 'none'`,
    // Images allowed from extension and data URIs
    `img-src ${webview.cspSource} data:`,
    // Frame control
    `frame-src 'none'`,
  ].join('; ');
}

/**
 * Webview Provider for the ARC1610 sidebar chat interface.
 * 
 * Handles the lifecycle of the webview, message routing to the agent loop,
 * configuration updates, and indexing status reporting.
 */

import * as vscode from 'vscode';
import { AgentLoop } from '../agent/agentLoop';
import { CodebaseIndexer } from '../indexing/indexer';
import { ProviderRegistry } from '../providers/registry';
import { ChatMessage } from '../providers/types';
import { Logger } from '../utils/logger';
import { ExtensionToWebviewMessage, validateWebviewMessage, WebviewToExtensionMessage } from './messageTypes';
import { getCsp } from './securityPolicy';
import { OllamaManager } from '../utils/ollamaManager';

export class Arc1610ViewProvider implements vscode.WebviewViewProvider {
  public static readonly viewType = 'arc1610.chatView';
  
  private view?: vscode.WebviewView;
  private chatHistory: ChatMessage[] = [];
  private agent: AgentLoop | null = null;
  private readonly logger = Logger.getInstance();

  constructor(
    private readonly extensionUri: vscode.Uri,
    private readonly providerRegistry: ProviderRegistry,
    private readonly indexer: CodebaseIndexer,
  ) {}

  public resolveWebviewView(
    webviewView: vscode.WebviewView,
    context: vscode.WebviewViewResolveContext,
    _token: vscode.CancellationToken,
  ) {
    this.view = webviewView;

    // Set webview options
    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [this.extensionUri],
    };

    // Set HTML content
    webviewView.webview.html = this.getHtmlForWebview(webviewView.webview);

    // Handle messages from the webview
    webviewView.webview.onDidReceiveMessage(
      (data) => this.handleMessage(data),
      undefined,

    webviewView.webview.onDidReceiveMessage(
      (data) => this.handleMessage(data),
      undefined,
      [], // disposables
    );
    
    // Send initial configuration and index status
    this.sendConfig();
    this.sendIndexStatus();
    
    // Subscribe to indexer progress events
    this.indexer.onProgress((progress) => {
      this.postMessage({ type: 'indexingProgress', progress });
      if (progress.status === 'complete' || progress.status === 'error' || progress.status === 'cancelled') {
        this.sendIndexStatus();
      }
    });
  }

  /**
   * Start a new chat session.
   */
  public newChat() {
    this.chatHistory = [];
    this.agent?.cancel();
    this.agent = null;
    
    if (this.view) {
      this.postMessage({ type: 'newSession' } as any); 
    }
  }

  /**
   * Navigate the webview to a specific path.
   */
  public navigateTo(path: string) {
    if (this.view) {
      this.view.show?.(true);
      this.postMessage({ type: 'navigateTo', path } as any);
    }
  }

  /**
   * Add context to the current chat (from editor commands).
   */
  public addContext(filepath: string, content?: string, selection?: string) {
    if (this.view) {
      this.view.show?.(true);
      this.postMessage({
        type: 'addContext',
        filepath,
        content,
        selection,
      });
    }
  }

  /**
   * Send configuration to the webview.
   */
  public async sendConfig() {
    try {
      const config = await this.providerRegistry.readConfig();
      const hasApiKey = Boolean(config.apiKey && config.apiKey.length > 0);
      
      this.postMessage({
        type: 'config',
        provider: config.provider,

      this.postMessage({
        type: 'config',
        provider: config.provider,
        model: config.modelName,
        hasApiKey,
        availableProviders: this.providerRegistry.getSupportedProviders(),
      });
    } catch (e) {
      this.logger.error('Failed to send config', e);
    }
  }

  /**
   * Send index status to the webview.
   */
  public sendIndexStatus() {
    const status = this.indexer.getStatus();
    this.postMessage({
      type: 'indexStatus',
      indexed: status.indexed,
      entryCount: status.entryCount,
      fileCount: status.fileCount,
      inProgress: status.inProgress,
    });
  }

  private postMessage(message: ExtensionToWebviewMessage) {
    this.view?.webview.postMessage(message);
  }

  private async handleMessage(data: unknown) {
    const msg = validateWebviewMessage(data);
    if (!msg) {
      this.logger.warn('Received invalid message from webview', data);
      return;
    }

    try {
      switch (msg.type) {
        case 'webviewReady':
          this.sendConfig();
          this.sendIndexStatus();
          break;
          
        case 'sendMessage':
          await this.handleUserMessage(msg.text, msg.contextFiles);
          break;
          
        case 'cancelGeneration':
          this.agent?.cancel();
          this.postMessage({ type: 'streamCancelled' });
          break;
          
        case 'newChat':
          this.newChat();
          break;
          
        case 'executeCommand':
          if (msg.args && msg.args.length > 0) {
            vscode.commands.executeCommand(msg.command, ...msg.args);
          } else {
            vscode.commands.executeCommand(msg.command);
          }

      } else {
        vscode.commands.executeCommand(msg.command);
      }
      break;
      
    case 'approveAction':
      if (this.agent) {
        this.agent.resolveApproval(msg.approved);
      }
      break;
      
    case 'getConfig':
      await this.sendConfig();
      break;
      
    case 'setProvider':
      await vscode.workspace.getConfiguration('arc1610').update('provider', msg.provider, true);
      await this.sendConfig();
      break;
      
    case 'setModel':
      await vscode.workspace.getConfiguration('arc1610').update('modelName', msg.model, true);
      await this.sendConfig();
      break;
      
    case 'setApiKey':
      await this.providerRegistry.setApiKey(msg.provider, msg.key);
      await this.sendConfig();
      break;
      
    case 'testConnection':
      try {
        const provider = await this.providerRegistry.getProvider();
        const models = await provider.testConnection();
        this.postMessage({ type: 'connectionResult', success: true, models });
      } catch (e) {
        this.postMessage({ 
          type: 'connectionResult', 
          success: false, 
          error: e instanceof Error ? e.message : String(e) 
        });
      }
      break;
      
    case 'startIndexing':
      this.indexer.indexWorkspace(msg.fullReindex);
      break;
      
    case 'cancelIndexing':
      this.indexer.cancelIndexing();
      break;
      
    case 'getIndexStatus':
      this.sendIndexStatus();
      break;
  }
} catch (error) {

          break;
      }
    } catch (error) {
      this.logger.error(`Error handling webview message: ${msg.type}`, error);
    }
  }

  private async handleUserMessage(text: string, contextFiles?: string[]) {
    try {
      const config = await this.providerRegistry.readConfig();
      
      // Ensure Ollama is running if selected
      if (config.provider === 'ollama') {
        const isRunning = await OllamaManager.ensureRunning(config.endpoint);
        if (!isRunning) {
          this.postMessage({ type: 'streamError', error: 'Ollama is not running. Please start it to arc.' });
          this.postMessage({ type: 'streamDone' });
          return;
        }
      }

      // Ensure index is loaded
      await this.indexer.ensureLoaded();
      
      const provider = await this.providerRegistry.getProvider();
      
      // Save user message to history
      this.chatHistory.push({ role: 'user', content: text });
      
      const requireApproval = vscode.workspace.getConfiguration('arc1610').get<boolean>('agent.requireApproval', true);
      const maxIterations = vscode.workspace.getConfiguration('arc1610').get<number>('agent.maxIterations', 15);
      
      if (this.agent) {
        this.agent.cancel();
      }
      this.agent = new AgentLoop(this.indexer, requireApproval);
      
      // Note: In a robust implementation, we would append the full agent history (including tools).
      // Here, we simplify by passing the accumulated user/assistant history.
      const historyToPass = [...this.chatHistory];
      // Pop the last user message so we can pass it separately to `run`
      historyToPass.pop();
      
      const generator = this.agent.run(text, historyToPass, provider, {
        model: config.modelName || undefined,

      
      const generator = this.agent.run(text, historyToPass, provider, {
        model: config.modelName || undefined,
        maxTokens: config.maxTokens,
        maxIterations: maxIterations,
        contextFiles,
      });

      let accumulatedContent = '';

      for await (const event of generator) {
        switch (event.type) {
          case 'content':
            accumulatedContent += event.content;
            this.postMessage({ type: 'streamContent', content: event.content });
            break;
            
          case 'toolCall':
            this.postMessage({ type: 'toolCall', toolName: event.toolName, args: event.args });
            break;
            
          case 'toolResult':
            this.postMessage({ 
              type: 'toolResult', 
              toolName: event.toolName, 
              content: event.result.content,
              success: event.result.success
            });
            break;
            
          case 'approval':
            this.postMessage({
              type: 'approvalRequest',
              toolName: event.toolName,
              description: event.description,
              diff: event.diff,
              filepath: event.filepath
            });
            break;
            
          case 'error':
            this.postMessage({ type: 'streamError', error: event.error });
            break;
            
          case 'cancelled':
            this.postMessage({ type: 'streamCancelled' });
            break;
            
          case 'done':
            this.postMessage({ type: 'streamDone' });
            if (accumulatedContent) {
              this.chatHistory.push({ role: 'assistant', content: accumulatedContent });
            }
            break;

              this.chatHistory.push({ role: 'assistant', content: accumulatedContent });
            }
            break;
        }
      }
    } catch (error) {
      this.logger.error('Failed to handle user message', error);
      this.postMessage({ 
        type: 'streamError', 
        error: error instanceof Error ? error.message : String(error) 
      });
    } finally {
      this.agent = null;
    }
  }

