  private convertMessages(messages: ChatMessage[]): OpenAIChatMessage[] {
    return messages.map(msg => {
      const oaiMsg: OpenAIChatMessage = {
        role: msg.role,
        content: msg.content,
      };
      if (msg.toolCalls) {
        oaiMsg.tool_calls = msg.toolCalls.map(tc => ({
          id: tc.id,
