/** A single streamed chunk from the model. */
export interface StreamChunk {
  /** Text content delta */
  content?: string;
  /** Tool call deltas */
  toolCalls?: Partial<ToolCall>[];
  /** Whether this is the final chunk */
  done?: boolean;
