  vision: boolean;
}

/**
 * The core LLM provider interface.
 * All providers must implement this to work with ARC1610's agent loop.
 */
export interface ILLMProvider {
  /** Unique provider identifier (e.g., 'ollama', 'openai', 'anthropic') */
  readonly id: string;
